sources.loop_rule:
fn pure(l: *Loops, loop: Index) bool {
    for (l.spanAt(l.node(loop).rhs)) |s| if (!l.pureNode(s, loop)) return false;
    return true;
}

fn pureNode(l: *Loops, i: Index, loop: Index) bool {
    const n = l.node(i);
    switch (n.kind) {
        .try_expr, .break_stmt, .return_stmt => return false,
        .binding => if (l.outside(l.text(n.main_token), loop)) return false,
        .assign => {
            var root = n.lhs;
            while (l.node(root).kind == .member) root = l.node(root).lhs;
            if (l.outside(l.text(l.node(root).main_token), loop)) return false;
        },
        .member, .member_call, .call => {
            if (l.effectful(n.lhs)) return false;
            if (n.kind != .member) for (l.spanAt(n.rhs)) |a| {
                const arg = if (l.node(a).kind == .named_arg) l.node(a).lhs else a;
                if (l.effectful(arg)) return false;
            };
            switch (l.k.callee[i]) {
                .prelude => |p| if (std.mem.eql(u8, prelude.fns[p].recv, "Process")) return false,
                else => {},
            }
        },
        else => {},
    }
    var it = Children.of(l.k.tree, i);
    while (it.next()) |c| if (!l.pureNode(c, loop)) return false;
    return true;
}

/// A value of a capability, handle, or kept-asker type: answering an ask is an effect on
/// the asker, as sending to a handle is (step 31).
fn effectful(l: *Loops, i: Index) bool {
    const t = l.k.pool.get(l.k.pool.base(l.k.typeOf(i)));
    return t.tag == .cap or t.tag == .handle or t.tag == .reply;
}

sources.formatter_context:
/// MO0501 alone, for `mo fmt --check`: the loop rule over a file that parses, whatever
/// else the checker finds in it.
pub fn loopFindings(gpa: std.mem.Allocator, source: []const u8, out: *diag.List) Error!void {
    var scratch: diag.List = .empty;
    const tokens = try lexer.lex(gpa, source, &scratch);
    const tree = try parser.parse(gpa, source, tokens, &scratch);
    const checked = try check.check(gpa, tree, &scratch);
    try loops.check(gpa, checked, out);
}

/// The stages through check; null when `stage` stops before lowering.
fn front(gpa: std.mem.Allocator, prog: program.Program, stage: Stage, diags: *diag.List) Error!?check.Checked {
    // What stopped the loader.
    if (diags.items.len > 0) return error.Rejected;
    const tokens = try lexer.lex(gpa, prog.source, diags);
    if (stage == .lex) return null;
    // One file is one module, so a second module line in it does not parse.
    const tree = if (prog.files.len == 1)
        try parser.parse(gpa, prog.source, tokens, diags)
    else
        try parser.parseProgram(gpa, prog.source, tokens, diags);
    if (stage == .parse) return null;
    const checked = try check.checkProgram(gpa, tree, prog.bases, prog.verified_lines, diags);
    try oneMain(gpa, checked, diags);
    try caps.check(gpa, checked, diags);
    try loops.check(gpa, checked, diags);
    if (diags.items.len > 0) {
        try fix.attach(gpa, checked, diags.items);
        return error.Rejected;
    }

