if (is_fmt) {
    const source = try Io.Dir.cwd().readFileAlloc(io, path, arena, .limited(1 << 20));
    const files: []const mo.diag.File = &.{.{ .path = path, .source = source }};
    const formatted = mo.fmt.format(arena, source, &diags) catch |e| switch (e) {
        error.Rejected => return reject(out, err, files, diags.items, json),
        else => return e,
    };
    switch (fmt_mode) {
        .stdout => try out.writeAll(formatted),
        .write => if (!std.mem.eql(u8, source, formatted)) {
            try Io.Dir.cwd().writeFile(io, .{ .sub_path = path, .data = formatted });
        },
        .check => {
            // The loop rule (MO0501) is the formatter's to enforce, and the checker's.
            var findings: mo.diag.List = .empty;
            try mo.pipeline.loopFindings(arena, source, &findings);
            const changed = !std.mem.eql(u8, source, formatted);
            if (changed) try mo.diff.unified(arena, out, path, source, formatted);
            if (changed or findings.items.len > 0) return reject(out, err, files, findings.items, json);
        },
    }
    return;
}

sources.corpus:
/// `mo fmt --check` on one file: true when formatting changes nothing and the loop
/// rule finds nothing.
pub fn fmtCheck(gpa: std.mem.Allocator, io: Io, root: []const u8, rel: []const u8) !bool {
    var dir = try Io.Dir.cwd().openDir(io, root, .{});
    defer dir.close(io);
    var arena_state = std.heap.ArenaAllocator.init(gpa);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    const source = try dir.readFileAlloc(io, rel, arena, .limited(1 << 20));
    // A rejects file that expects a syntax code does not parse, so it has no one shape.
    if (isRejectsPath(rel)) if (expectedCode(source)) |code| if (std.mem.startsWith(u8, code, "MO01")) return true;
    var diags: diag.List = .empty;
    const formatted = fmt.format(arena, source, &diags) catch |err| switch (err) {
        error.Rejected => {
            std.debug.print("corpus: {s} does not format: {s} {s}\n", .{ rel, diags.items[0].code, diags.items[0].what });
            return false;
        },
        else => return err,
    };
    if (!std.mem.eql(u8, source, formatted)) {
        std.debug.print("corpus: {s} is not formatted; run mo fmt on it\n", .{rel});
        return false;
    }
    var findings: diag.List = .empty;
    pipeline.loopFindings(arena, source, &findings) catch |err| switch (err) {
        error.Rejected => {},
        else => return err,
    };
    if (findings.items.len > 0) {
        std.debug.print("corpus: {s} at byte {d}: {s} {s}\n", .{ rel, findings.items[0].at, findings.items[0].code, findings.items[0].what });
        return false;
    }
    return true;
}
